<?php require_once __DIR__.'/../config/bootstrap.php'; Auth::requireRole(['admin','accountant']); $error=$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['_csrf']??null);try{$st=$pdo->prepare('INSERT INTO funding_sources(name,type) VALUES(?,?)');$st->execute([trim($_POST['name']),trim($_POST['type'])]);$success='Funding source created.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query('SELECT * FROM funding_sources ORDER BY id DESC')->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Funding Sources · LedgerFlow</title><link rel="stylesheet" href="assets/app.css"></head><body><aside class="sidebar"><div class="brand">Ledger<span>Flow</span></div><nav><a href="index.php">Dashboard</a><a href="transactions.php">Transactions</a><a href="customers.php">Customers</a><a class="active" href="funding_sources.php">Funding Sources</a><a href="reports.php">Reports</a><a href="api_docs.php">API Docs</a></nav><div class="side-bottom"><span><?=e(Auth::user()['name'])?></span><a href="logout.php">Sign out</a></div></aside><main class="main"><header><div><p class="eyebrow">CONFIGURATION</p><h1>Funding Sources</h1><p class="muted">Manage sources used when recording incoming funds.</p></div></header><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><div class="panel-head"><h2>Add funding source</h2></div><form method="post" class="grid-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Name<input name="name" required></label><label>Type<input name="type" placeholder="bank, card, cash" required></label><div><button class="btn primary">Create</button></div></form></section><section class="panel"><div class="panel-head"><h2>Sources</h2></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><span class="badge posted"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
